pub fn first_even(v: &[i32]) -> Option<i32> {
    for &n in v {
        if n % 2 == 0 {
            return n;
        }
    }
    None
}

pub fn run() -> (Option<i32>, Option<i32>) {
    (first_even(&[1, 3, 4, 5]), first_even(&[1, 3, 5]))
}

