exercises.solution:
pub fn shout(name: Option<String>) -> String {
    name.map(|n| n.to_uppercase())
        .unwrap_or_else(|| String::from("ANONYMOUS"))
}

pub fn run() -> (String, String) {
    (
        shout(Some(String::from("ferris"))),
        shout(None),
    )
}

