pub fn total(raw: &[&str]) -> Option<i64> {
    let mut sum = 0i64;
    for s in raw {
        sum += s.parse::<i64>().ok();
    }
    Some(sum)
}

pub fn run() -> (Option<i64>, Option<i64>, Option<i64>) {
    (
        total(&["1", "2", "39"]),
        total(&["1", "oops", "39"]),
        total(&[]),
    )
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn sums_or_gives_up() {
        assert_eq!(run(), (Some(42), None, Some(0)));
    }
}

